                Vec3 orth = new Vec3(-Mth.cos(-this.getYRot() * Mth.DEG_TO_RAD - (float) Math.PI), 0, Mth.sin(-this.getYRot() * Mth.DEG_TO_RAD - (float) Math.PI));
