public static boolean applyDamage(Entity target, float baseAmount, DamageSource damageSource) {
        if (target instanceof LivingEntity livingTarget && damageSource instanceof SpellDamageSource spellDamageSource) {
            var e = new SpellDamageEvent(livingTarget, baseAmount, spellDamageSource);
            if (NeoForge.EVENT_BUS.post(e).isCanceled()) {
                return false;
            }
            baseAmount = e.getAmount();
            float adjustedDamage = baseAmount * getResist(livingTarget, spellDamageSource.spell.getSchoolType());
            if (damageSource.getDirectEntity() instanceof NoKnockbackProjectile) {
                ignoreNextKnockback(livingTarget);
            }
            if (damageSource.getEntity() instanceof LivingEntity livingAttacker) {
                if (isFriendlyFireBetween(livingAttacker, livingTarget)) {
                    return false;
                }
                livingAttacker.setLastHurtMob(target);
            }
            return livingTarget.hurt(damageSource, adjustedDamage);
        } else {
            return target.hurt(damageSource, baseAmount);
        }
    }

@Override
    public void tick() {
        super.tick();
        // swirling line towards destination during delay
        if (startPos != null && !level.isClientSide && tickCount < getDelay()) {
            float f = tickCount / (float) getDelay();
            Vec3 forward = position().subtract(startPos).multiply(1, 0, 1).normalize();
            Vec3 right = new Vec3(-forward.z, 0, forward.x);
            Vec3 spawn = startPos.lerp(position(), f);
            float phase = tickCount * 0.5f;
            float threshold = 3;
            float distance = (float) position().subtract(spawn).horizontalDistance();
            float strength = distance > threshold ? 1 : distance / threshold;
            Vec3 oscillation = right.scale(Mth.sin(phase) * 2 * strength);
            spawn = Utils.moveToRelativeGroundLevel(level, spawn.add(oscillation), 6);
            float yrot = Utils.getAngle(startPos.x, startPos.z, getX(), getZ());
            if (!level.getBlockState(BlockPos.containing(spawn).below()).isAir()) {
                ExtendedEvokerFang fang = new ExtendedEvokerFang(level, spawn.x, spawn.y, spawn.z, yrot, 0, this.getOwner() instanceof LivingEntity e ? e : null, this.getDamage());
                level.addFreshEntity(fang);
            }
        }
    }

@Override
    public void onCast(Level level, int spellLevel, LivingEntity entity, CastSource castSource, MagicData playerMagicData) {
        Vec3 dest = null;
        if (playerMagicData.getAdditionalCastData() instanceof TargetEntityCastData castTargetingData) {
            LivingEntity target = castTargetingData.getTarget((ServerLevel) level);
            if (target != null) {
                dest = target.position();
            }
        }
        if (dest == null) {
            HitResult raycast = RaycastBuilder.begin(level, entity)
                    .range(getRange(spellLevel, entity))
                    .checkForBlocks(true)
                    .bbInflation(0.35f)
                    .build();
            if (raycast.getType() == HitResult.Type.ENTITY) {
                dest = ((EntityHitResult) raycast).getEntity().position();
            } else {
                dest = raycast.getLocation().subtract(entity.getForward().normalize());
            }
        }
        dest = Utils.moveToRelativeGroundLevel(level, dest, 6);
        Vec3 start = entity.position();
        float horizontalDist = (float) dest.subtract(start).horizontalDistance();
        int delay = Math.max(8, Math.min(40, Mth.ceil(horizontalDist * 1.5f))) * 2/ 3;

        FangSwirlEntity swirl = new FangSwirlEntity(EntityRegistry.FANG_SWIRL.get(), level);
        swirl.moveTo(dest.x, dest.y, dest.z);
        swirl.setStartPos(start);
        swirl.setDelay(delay);
        swirl.setRadius(getSwirlRadius(spellLevel, entity));
        swirl.setDuration(getSwirlDurationTicks(spellLevel, entity));
        swirl.setOwner(entity);
        swirl.setDamage(getDamage(spellLevel, entity));
        level.addFreshEntity(swirl);
        super.onCast(level, spellLevel, entity, castSource, playerMagicData);
    }

@Override
    protected void checkHits() {
        if (level.isClientSide) {
            return;
        }
        float radius = getRadius();
        if (radius < 0.05f) {
            return;
        }
        float angle = (tickCount - getDelay()) * Mth.TWO_PI * 0.01f;
        float yawDeg = angle * Mth.RAD_TO_DEG;
        Vec3 axis = Vec3.directionFromRotation(0, yawDeg);
        float fangYawRad = (yawDeg - 90f) * Mth.DEG_TO_RAD;
        Vec3 center = position();
        LivingEntity owner = getOwner() instanceof LivingEntity e ? e : null;
        float density = 0.85f;
        int count = Mth.ceil((2 * radius / density)) + 1;
        for (int i = 0; i < count; i++) {
            double t = Mth.lerp(i / (count - 1f), -1.0, 1.0);
            Vec3 spawn = center.add(axis.scale(t * radius));
            spawn = Utils.moveToRelativeGroundLevel(level, spawn, 4);
            int delay = Math.abs((int) (t * radius * 0.5));
            ExtendedEvokerFang fang = new ExtendedEvokerFang(level, spawn.x, spawn.y, spawn.z, fangYawRad, delay, owner, getDamage());
            level.addFreshEntity(fang);
        }
    }

