private void doSummon() {
        boolean isSkeleton = random.nextDouble() < .3;
        Monster undead = isSkeleton ?
                new SummonedSkeleton(level, false) :
                new SummonedZombie(level, false);
        equip(undead, generateEquipment());
        undead.moveTo(this.position().add(0, 0.1, 0));
        undead.setYRot(this.getYRot());
        undead.finalizeSpawn((ServerLevel) level, level.getCurrentDifficultyAt(undead.getOnPos()), MobSpawnType.MOB_SUMMONED, null);
        SummonManager.setDuration(undead, 5 * 60 * 20);
        var owner = getSummoner();
        if (owner != null) {
            SummonManager.setOwner(undead, owner);
            if (forcedTarget != null) {
                undead.setTarget(forcedTarget);
            } else if (owner instanceof Mob mob) {
                undead.setTarget(mob.getTarget());
            }
        }
        undead.setDeltaMovement(this.getForward().add(0, 0.5, 0).scale(0.25));
        level.addFreshEntity(undead);
        Vec3 pos = this.position();
        MagicManager.spawnParticles(level, ParticleTypes.SMOKE, pos.x, pos.y + 1, pos.z, 25, 0.1, 0.3, 0.1, 0.1, false);
        level.playSound(null, pos.x, pos.y, pos.z, SoundEvents.TRIAL_SPAWNER_SPAWN_MOB, SoundSource.HOSTILE, 2f, 1.0f);
        level.playSound(null, pos.x, pos.y, pos.z, SoundEvents.VEX_AMBIENT, SoundSource.HOSTILE, 2f, 0.75f);
    }

private void vanish() {
        discard();
        Vec3 pos = this.position();
        MagicManager.spawnParticles(level, ParticleTypes.LARGE_SMOKE, pos.x, pos.y + 1, pos.z, 25, 0.1, 0.3, 0.1, 0.1, false);
        level.playSound(null, pos.x, pos.y, pos.z, SoundEvents.TRIAL_SPAWNER_SPAWN_MOB, SoundSource.HOSTILE, 2f, 0.5f);
    }

@Override
    protected void addAdditionalSaveData(CompoundTag compound) {
        compound.putInt("SummonedCount", this.summonedCount);
        compound.putInt("SummonsToSpawn", this.summonsToSpawn);
        compound.putInt("Delay", this.delay);
    }

@Override
    protected void readAdditionalSaveData(CompoundTag compound) {
        this.summonedCount = compound.getInt("SummonedCount");
        this.summonsToSpawn = compound.getInt("SummonsToSpawn");
        this.delay = compound.getInt("Delay");
    }

@Override
    public void onRemovedFromLevel() {
        super.onRemovedFromLevel();
        onRemovedHelper(this);
    }

@Override
    public boolean canUse() {
        // immediately short circuit and create new portal
        if (twinPortal) {
            return true;
        }
        // only use in ominous mode combat
        if (!(mob.isAggressive() && mob.isOminous())) {
            return false;
        }
        // cooldown
        if (--cooldown > 0) {
            return false;
        }
        // limit summon count and delay next check if we cannot use
        int summons = mob.level.getEntities(mob, mob.getBoundingBox().inflate(32), entity -> SummonManager.getOwner(entity) == mob).size();
        if (summons < 12) {
            return true;
        } else {
            cooldown = 20 * 5;
            return false;
        }
    }

@Override
    public void start() {
        Level level = mob.level;
        Entity target = mob.getTarget();
        if (target == null) {
            // should be impossible
            return;
        }
        List<? extends Entity> otherTargets = level.getEntitiesOfClass(target.getClass(), mob.getBoundingBox().inflate(20, 10, 20), entity -> !entity.isSpectator() && Utils.hasLineOfSight(level, mob, entity, false));
        if (!otherTargets.isEmpty()) {
            target = otherTargets.get(mob.getRandom().nextInt(otherTargets.size()));
        }

        int summonCount = 5 + (int) Mth.lerp(1 - mob.getHealth() / mob.getMaxHealth(), 0, 5 + 1);
        int delay = 20;
        this.cooldown = summonCount * delay * 2;

        UndeadRiftEntity rift = new UndeadRiftEntity(level);
        SummonManager.setOwner(rift, mob);
        rift.setDelay(delay);
        rift.setSummonsToSpawn(summonCount);
        Vec3 dir = new Vec3(0, 0, 1).yRot(
                (-target.getYRot() - 90 + mob.getRandom().nextInt(180)) * Mth.DEG_TO_RAD
        ).add(0, -.2, 0).normalize();
        Vec3 targetPos = level.clip(new ClipContext(
                target.getBoundingBox().getCenter(), target.getBoundingBox().getCenter().add(dir.scale(4.5 + target.getBbWidth())),
                ClipContext.Block.COLLIDER, ClipContext.Fluid.ANY, CollisionContext.empty())).getLocation();
        targetPos = Utils.moveToRelativeGroundLevel(level, targetPos.subtract(dir), 3, 10);
        rift.moveTo(targetPos);
        Utils.fudgeNoCollision(level, rift);
        rift.setYRot(Utils.getAngle(targetPos.x, targetPos.z, target.getX(), target.getZ()) * Mth.RAD_TO_DEG + 90);
        rift.setForcedTarget((LivingEntity) target); // safe cast because the entities of class must extend living entity by proxy of getTarget returning a living entity
        level.addFreshEntity(rift);
        MagicManager.spawnParticles(level, ParticleTypes.LARGE_SMOKE, targetPos.x, targetPos.y + 1, targetPos.z, 50, 0.1, 0.3, 0.1, 0.1, false);
        level.playSound(null, targetPos.x, targetPos.y, targetPos.z, SoundEvents.TRIAL_SPAWNER_SPAWN_MOB, SoundSource.HOSTILE, 2f, 1.0f);
        level.playSound(null, targetPos.x, targetPos.y, targetPos.z, SoundEvents.VEX_AMBIENT, SoundSource.HOSTILE, 2f, 0.75f);
        if (twinPortal) {
            twinPortal = false;
        } else if (mob.getRandom().nextFloat() < .2f) {
            twinPortal = true;
            cooldown = 10;
        }
    }

public static void setOwner(@NotNull Entity summon, @NotNull Entity owner) {
        removeSummon(summon);
        INSTANCE.summonToOwner.put(summon.getUUID(), owner.getUUID());
        startTrackingSummon(owner, summon);
        IronsDataStorage.INSTANCE.setDirty();
        if (owner.level() instanceof ServerLevel) {
            NeoForge.EVENT_BUS.post(new SetSummonOwnerEvent(owner, summon));
        }
    }

public static @Nullable Entity getOwner(@NotNull Entity summon) {
        if (summon.level instanceof ServerLevel serverLevel) {
            if (INSTANCE.summonToOwner.containsKey(summon.getUUID())) {
                return serverLevel.getEntity(INSTANCE.summonToOwner.get(summon.getUUID()));
            }
        }
        return null;
    }

public static void setDuration(Entity summon, int duration) {
        if (!(summon.level instanceof ServerLevel serverLevel)) return;
        INSTANCE.summonExpirations.add(new ExpirationInstance(summon.getUUID(), serverLevel.getServer().getTickCount(), serverLevel.getServer().getTickCount() + duration));
    }
